describe('Notification Dismissal', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.viewport(1280, 720);
  });

  it('should dismiss a notification when close button is clicked', () => {
    // Trigger a notification to appear
    cy.get('[data-testid="trigger-notification"]').click();

    // Verify notification is visible
    cy.get('[data-testid="notification-container"]')
      .should('be.visible')
      .and('contain', 'Notification message');

    // Click the close button
    cy.get('[data-testid="notification-close-btn"]').click();

    // Verify notification is dismissed
    cy.get('[data-testid="notification-container"]')
      .should('not.exist');
  });

  it('should dismiss multiple notifications independently', () => {
    // Trigger first notification
    cy.get('[data-testid="trigger-notification"]').click();
    cy.get('[data-testid="notification-container"]').should('be.visible');

    // Trigger second notification
    cy.get('[data-testid="trigger-notification"]').click();
    cy.get('[data-testid="notification-container"]').should('have.length', 2);

    // Close only the first notification
    cy.get('[data-testid="notification-close-btn"]').first().click();

    // Verify only one notification remains
    cy.get('[data-testid="notification-container"]').should('have.length', 1);

    // Close the remaining notification
    cy.get('[data-testid="notification-close-btn"]').click();

    // Verify all notifications are dismissed
    cy.get('[data-testid="notification-container"]').should('not.exist');
  });

  it('should handle rapid close button clicks without errors', () => {
    // Trigger notification
    cy.get('[data-testid="trigger-notification"]').click();
    cy.get('[data-testid="notification-container"]').should('be.visible');

    // Attempt rapid clicks on close button
    cy.get('[data-testid="notification-close-btn"]')
      .click()
      .click();

    // Verify notification is dismissed and no errors occur
    cy.get('[data-testid="notification-container"]').should('not.exist');
    cy.get('body').should('not.have.class', 'error');
  });

  it('should dismiss notification with keyboard accessibility', () => {
    // Trigger notification
    cy.get('[data-testid="trigger-notification"]').click();
    cy.get('[data-testid="notification-container"]').should('be.visible');

    // Focus and activate close button with keyboard
    cy.get('[data-testid="notification-close-btn"]')
      .focus()
      .should('have.focus')
      .type('{enter}');

    // Verify notification is dismissed
    cy.get('[data-testid="notification-container"]').should('not.exist');
  });

  it('should dismiss notification with correct animation', () => {
    // Trigger notification
    cy.get('[data-testid="trigger-notification"]').click();
    cy.get('[data-testid="notification-container"]')
      .should('be.visible')
      .and('have.css', 'opacity', '1');

    // Click close button
    cy.get('[data-testid="notification-close-btn"]').click();

    // Verify animation occurs before removal
    cy.get('[data-testid="notification-container"]')
      .should('have.class', 'dismissing');

    // Verify notification is removed after animation
    cy.get('[data-testid="notification-container"]', { timeout: 1000 })
      .should('not.exist');
  });
});
